// [Human_proxy] Comprometer · Preparación del compromiso
// Normaliza la entrada, ajusta el momento al horario de trabajo (laborables de 8:00 a 20:30, hora de Madrid)
// y calcula la fecha de fin y la línea del compromiso.
const { acto, accion, chat_id, contenido, simbolos, condicion, nivel, dia, hora, fin, ahora } = input;

const txt = x => (x === undefined || x === null) ? '' : String(x);
const limpio = x => txt(x).trim();
const p2 = n => String(n).padStart(2, '0');

// Hora de Madrid: +2 entre el último domingo de marzo y el último de octubre (a la 01:00 UTC), +1 el resto del año
const ultimoDomingo = (anio, mes) => { const d = new Date(Date.UTC(anio, mes + 1, 0, 1)); d.setUTCDate(d.getUTCDate() - d.getUTCDay()); return d; };
const desfase = utc => { const a = utc.getUTCFullYear(); return (utc >= ultimoDomingo(a, 2) && utc < ultimoDomingo(a, 9)) ? 2 : 1; };
const aMadrid = utc => { const m = new Date(utc.getTime() + desfase(utc) * 3600e3); return { Y: m.getUTCFullYear(), M: m.getUTCMonth() + 1, D: m.getUTCDate(), h: m.getUTCHours(), mi: m.getUTCMinutes(), d: m.getUTCDay() }; };
const deMadrid = (Y, M, D, h, mi) => { for (const o of [1, 2]) { const u = new Date(Date.UTC(Y, M - 1, D, h, mi) - o * 3600e3); if (desfase(u) === o) return u; } return new Date(Date.UTC(Y, M - 1, D, h, mi) - 3600e3); };
const masDias = (l, n, h, mi) => { const f = new Date(Date.UTC(l.Y, l.M - 1, l.D + n)); return deMadrid(f.getUTCFullYear(), f.getUTCMonth() + 1, f.getUTCDate(), h, mi); };
const leer = texto => { const r = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})$/.exec(texto); if (!r) throw new Error('Fecha u hora no válida: ' + texto); return deMadrid(+r[1], +r[2], +r[3], +r[4], +r[5]); };

// 1. Entrada normalizada
const cm_acto = (limpio(acto) || 'DECISION').toUpperCase();
const cm_accion = limpio(accion).toLowerCase();
const cm_chat = limpio(chat_id);
const cm_contenido = limpio(contenido);
const cm_simbolos = limpio(simbolos).replace(/ /g, '').toUpperCase();
const cm_condicion = limpio(condicion);
const cm_nivel_txt = txt(nivel) !== '' ? nivel : 0;

// Fecha y hora pedidas: el día que llega o hoy; la hora que llega, las 08:00 si hay día o la hora actual si no
const hoy = aMadrid(ahora ? new Date(ahora) : new Date());
const diaPedido = txt(dia) !== '' ? txt(dia) : `${hoy.Y}-${p2(hoy.M)}-${p2(hoy.D)}`;
const horaPedida = txt(hora) !== '' ? txt(hora) : (txt(dia) !== '' ? '08:00' : `${p2(hoy.h)}:${p2(hoy.mi)}`);
const pedido = leer(`${diaPedido} ${horaPedida}`);

// 2. Momento ajustado al horario de trabajo
const l = aMadrid(pedido);
const laborable = l.d >= 1 && l.d <= 5;
const minutos = l.h * 60 + l.mi;
const tramo = minutos < 8 * 60 ? 'antes' : (minutos <= 20 * 60 + 30 ? 'dentro' : 'despues');
const saltos = l.d === 5 ? 3 : (l.d === 6 ? 2 : 1); // al siguiente laborable
let momento;
if (laborable && tramo === 'dentro') momento = pedido;
else if (laborable && tramo === 'antes') momento = deMadrid(l.Y, l.M, l.D, 8, 0);
else momento = masDias(l, saltos, 8, 0);
const cm_aplazado = (laborable && tramo === 'dentro') ? 'no' : 'si';
const lm = aMadrid(momento);

// 3. Con quién y de qué tipo
const escribeAlChat = ['informar', 'preguntar', 'abstenerse'].includes(cm_accion);
const chatReal = (cm_chat === '' || cm_chat === 'GLOBAL') ? '' : cm_chat;
const cm_dest = escribeAlChat ? chatReal : '';
const cm_con = (cm_acto === 'REQUEST' && chatReal) ? chatReal : 'yo';
const cm_tipo = ({ agendar: 'DO', estudiar: 'DO', cotizar: 'DO', investigar: 'DO', informar: 'INFORM', preguntar: 'REQUEST', abstenerse: 'REFRAIN' })[cm_accion] || '';

// 4. Fin, momento legible y línea del compromiso
let finFecha = null;
if (txt(fin) !== '') finFecha = leer(`${limpio(fin)} 20:30`);
else if (cm_accion === 'abstenerse') finFecha = null;
else if (cm_condicion !== '') finFecha = masDias(lm, 7, lm.h, lm.mi);
else if (cm_accion === 'estudiar') finFecha = deMadrid(lm.Y, lm.M, lm.D, 20, 30);
const cm_fin = finFecha ? finFecha.toISOString() : '';
const cm_cuando = `${p2(lm.D)}/${p2(lm.M)} a las ${p2(lm.h)}:${p2(lm.mi)}`;
const nucleo = `(${cm_tipo} ${p2(lm.D)}/${p2(lm.M)} ${p2(lm.h)}:${p2(lm.mi)} ${cm_accion}${cm_dest ? ' chat:' : ''}${cm_dest} «${cm_contenido}»)`;
const cm_linea = cm_condicion ? `(IF (B «${cm_condicion}») ${nucleo})` : nucleo;

return {
  cm_acto, cm_accion, cm_chat, cm_contenido, cm_simbolos, cm_condicion, cm_nivel_txt,
  cm_momento: momento.toISOString(), cm_aplazado, cm_dest, cm_con, cm_tipo,
  cm_fin, cm_cuando, cm_linea,
};
